void Solver::bump_var(int var, double coeff) {
    double inc = var_inc * coeff;
    double new_act = activity[var] + inc;
    if (new_act > 1e100) {
        const double factor = 1e-100;
        for (int i = 1; i <= vars; ++i) activity[i] *= factor;
        var_inc *= factor;
        new_act *= factor;
    }
    activity[var] = new_act;
    if (vsids.inHeap(var)) vsids.update(var);
}
